package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PictureUrlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property picture url of user profile ")
  void test_picture_url_v_o_builder() {
    Assertions.assertFalse(PictureUrlVO.nullValue().getPictureUrl().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(PictureUrlVO.tryFrom(null).getPictureUrl().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", PictureUrlVO.from("one").getPictureUrl().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> PictureUrlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", PictureUrlVO.from("one").toString());
  }
}
